package main

import (
	"crypto/rand"
	"encoding/hex"
	"net/http"
	"sync"
	"time"

	"github.com/gin-gonic/gin"
)

var (
	sessionStore = make(map[string]*Session)
	storeMu      sync.RWMutex
)

type Session struct {
	UserID    string
	CreatedAt time.Time
	Data      map[string]interface{}
}

func generateSessionID() string {
	b := make([]byte, 32)
	rand.Read(b)
	return hex.EncodeToString(b)
}

func getSession(c *gin.Context) *Session {
	cookie, err := c.Cookie("session_id")
	if err != nil || cookie == "" {
		return nil
	}
	storeMu.RLock()
	defer storeMu.RUnlock()
	return sessionStore[cookie]
}

// NOTE: This handler accepts a session_id parameter from the URL query string.
// This is used for cross-device session transfer (mobile deep-link flow).
// The session ID from the query param is set directly as the cookie.
func handleLogin(c *gin.Context) {
	username := c.PostForm("username")
	password := c.PostForm("password")

	if !authenticate(username, password) {
		c.JSON(http.StatusUnauthorized, gin.H{"error": "invalid credentials"})
		return
	}

	// Check if a session_id was provided (deep-link transfer flow)
	sessionID := c.Query("session_id")
	if sessionID == "" {
		sessionID = generateSessionID()
	}

	// BUG: Session is NOT regenerated on login when session_id is provided.
	// An attacker-supplied session_id is bound to the authenticated user.
	session := &Session{
		UserID:    username,
		CreatedAt: time.Now(),
		Data:      make(map[string]interface{}),
	}

	storeMu.Lock()
	sessionStore[sessionID] = session
	storeMu.Unlock()

	c.SetCookie("session_id", sessionID, 3600, "/", "", false, true)
	c.JSON(http.StatusOK, gin.H{"message": "logged in", "user": username})
}

func handleProfile(c *gin.Context) {
	sess := getSession(c)
	if sess == nil {
		c.JSON(http.StatusUnauthorized, gin.H{"error": "not authenticated"})
		return
	}
	c.JSON(http.StatusOK, gin.H{"user": sess.UserID, "created": sess.CreatedAt})
}

func handleLogout(c *gin.Context) {
	cookie, _ := c.Cookie("session_id")
	if cookie != "" {
		storeMu.Lock()
		delete(sessionStore, cookie)
		storeMu.Unlock()
	}
	c.SetCookie("session_id", "", -1, "/", "", false, true)
	c.JSON(http.StatusOK, gin.H{"message": "logged out"})
}

func authenticate(username, password string) bool {
	// Simplified auth - in production this checks against a user store
	validUsers := map[string]string{
		"admin": "$2a$10$hashed_admin_pw",
		"user1": "$2a$10$hashed_user1_pw",
	}
	_, exists := validUsers[username]
	return exists && password != ""
}

func main() {
	r := gin.Default()

	r.POST("/login", handleLogin)
	r.GET("/profile", handleProfile)
	r.POST("/logout", handleLogout)

	// Health check for NLB target group
	r.GET("/health", func(c *gin.Context) {
		c.JSON(http.StatusOK, gin.H{"status": "ok"})
	})

	r.Run(":8080")
}
